'use strict'
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const repo=path.resolve(__dirname,'../../..'),root=path.join(repo,'.artifacts/deep-audit-round3-mobile-ui');
const name=process.argv[2];assert.match(name||'',/^[a-z0-9-]+$/);const dir=path.join(root,name);assert.ok(fs.existsSync(dir));
const sha=buf=>crypto.createHash('sha256').update(buf).digest('hex'),read=name=>JSON.parse(fs.readFileSync(path.join(dir,name)));
const receipt=read('result.json'),integrity=read('integrity.json'),cleanup=read('cleanup.json'),installed=read('installed.json'),manifest=read('source-before.json');
function validate(r){assert.equal(r.checks.length,12);assert.equal(new Set(r.checks.map(c=>c.name)).size,12);assert.equal(r.cleanupErrors.length,0);assert.deepEqual(r.findings.map(x=>x.id),['ROUND3-QUESTION-ACK-LIFETIME','ROUND3-QUESTION-RETRY-DRAFT']);assert.ok(r.boundary.startsWith('No Android'));assert.equal(r.browserFailures.length,0)}
validate(receipt);assert.equal(integrity.sourceDrift.length,0);assert.equal(cleanup.sockets,0);assert.equal(cleanup.serverListening,false);assert.equal(cleanup.pending,0);assert.equal(cleanup.clients,0);assert.equal(cleanup.cleanupErrors.length,0);
assert.equal(installed['@deepseek-ai/dsh-client-ui-user-questions'].sha256,'6f382a535cb182b062365773c57b23579e8195c0096901c1864c0b1ae0079457');
assert.equal(installed['@deepseek-ai/dsh-client-ui-conversation'].sha256,'30f413cc27be08f0b57a472440495b033ea8b708e281d465cd5bbe3e45cd0066');
let verified=0;for(const entry of read('freeze.json')){assert.equal(sha(fs.readFileSync(path.join(dir,entry.file))),entry.sha256);verified++}
const trace=receipt.browserTrace,normal=trace.find(x=>x.type==='rpc-submit'&&x.selected?.[0]?.id==='touch-normal');assert.ok(normal);assert.ok(trace.filter(x=>x.type==='ui-click'&&x.trusted&&x.t<normal.t).length>=2);
const eventTimings=[];for(const item of trace.filter(x=>x.type==='rpc-submit')){const label=item.selected?.[0]?.id,card=receipt.presentations.filter(x=>x.questions[0].id===label&&x.t<item.t).at(-1),removed=receipt.removals.find(x=>x.key===card?.key),ui=trace.filter(x=>x.type==='ui-click'&&x.text==='提交'&&x.t<item.t).at(-1),response=trace.find(x=>x.type==='http-response'&&x.rpcId===item.rpcId);eventTimings.push({label,rpcId:item.rpcId,presentationKey:card?.key,uiClick:ui?.t,cardRemoved:removed?.t,rpcSubmit:item.t,httpHeaders:response?.t,status:response?.status,clickToRpcMs:ui?item.t-ui.t:null,removedToHeadersMs:removed&&response?response.t-removed.t:null,rpcToHeadersMs:response?response.t-item.t:null})}
const held=eventTimings.find(x=>x.label==='same-tick-delayed');assert.ok(held.cardRemoved<held.rpcSubmit&&held.rpcSubmit<held.httpHeaders);assert.ok(held.rpcToHeadersMs>=350);
const posts=trace.filter(x=>x.type==='rpc-submit');assert.equal(posts.length,8);assert.equal(receipt.requests.length,8);assert.equal(receipt.serverTrace.filter(x=>x.type==='controlled-business-receipt').length,7);assert.equal(receipt.serverTrace.filter(x=>x.type==='controlled-business-rejection').length,1);
const retry=receipt.presentations.filter(x=>x.questions[0].id==='failed-before-dispatch');assert.equal(retry.length,2);assert.notEqual(retry[0].key,retry[1].key);
const negativeControls=[];for(const [label,mutate] of [['inflated check count',x=>x.checks.push(x.checks[0])],['removed finding',x=>x.findings.pop()],['claimed Android full chain',x=>x.boundary='Android fully validated'],['hidden browser error',x=>x.browserFailures.push('injected')]]){const altered=structuredClone(receipt);mutate(altered);assert.throws(()=>validate(altered));negativeControls.push({label,rejected:true})}
const summary={run:name,authorSelfCheck:true,independentAcceptance:false,checks:12,metadataNegativeControls:negativeControls,freezeVerified:verified,inputFiles:integrity.checked,sourceDrift:integrity.sourceDrift,uiRpcPosts:posts.length,httpPortRequests:receipt.requests.length,controlledBusinessReceipts:7,abortedOldRequest:1,preDispatch503:1,wrongCorrelationAfterSettlement:1,presentations:receipt.presentations.length,findings:receipt.findings,clock:{eventTimings:'one renderer performance.now; HTTP headers not parsed gateway ACK',serverTrace:'separate Node performance.now; never subtracted from renderer',percentiles:'none; small heterogeneous authored scenarios, not a latency distribution',resultDOM:'one actual AskQuestionRow/Card mount from observed controlled outcome via explicit test driver, not Host session projection',largeSyncSnapshot:'not loaded; no snapshot-load or throughput conclusion'},eventTimings,themeRequestDenials:receipt.networkDenials.length,cleanup,inputs:manifest.filter(x=>/patch-official-runtime|coverage-master|mobile-runtime\.js|mobile-compat\.css|dsh-api-gateway[/\\]lib[/\\](index|client)\.js|dsh-client-connection[/\\]lib[/\\](index|client)\.js/.test(x.file)),boundary:receipt.boundary};
const output=path.join(root,name+'-summary.json');assert.ok(!fs.existsSync(output));fs.writeFileSync(output,JSON.stringify(summary,null,2));console.log(JSON.stringify(summary));
